<!--vbase-->
<template>
  <SubHeader
    v-if="!onDashboard"
    name="workflow_logs"
    :label="$t('wf_workflow_logs')"
  />
  <div
    :class="
      onDashboard
        ? 'page-height-limit-dashboard line-height-dashboard-fix'
        : 'page-height-limit'
    "
  >
    <div class="row sticky-search-filter page-background">
      <q-input
        v-model="search_value"
        :label="$t('search')"
        :rules="[(new_search_value: any) => new_search_value.length >= 0]"
        @update:model-value="
          (new_search_value: any) => {
            inputSearchValueChanges(new_search_value);
          }
        "
        @clear:model-value="clearSearchValue"
        debounce="400"
        class="row-8 wf-log-search white-inputs"
        outlined
        hide-bottom-space
      >
        <template v-slot:append>
          <q-btn icon="tune" flat unelevated id="btn_tune_filters" />
          <q-menu
            class="q-pa-md filter-menu"
          >
            <!-- q-menu style because it is not working in class -->
            <div class="row q-my-sm width-400px">
              <span>{{ $t('sort_direction') }}</span>
              <q-space />
              <q-select
                v-model="sort_direction"
                :options="sort_direction_options_translated"
                :label="$t('sort_direction')"
                :clearable="false"
                dense
                outlined
                class="q-mr-sm width-180px"
              />
            </div>
            <div class="row q-my-sm width-400px">
              <span>{{ $t('sort_by') }}</span>
              <q-space />
              <q-select
                v-model="sort_by"
                :options="sort_by_options_translated"
                :label="$t('sort_by')"
                :clearable="false"
                dense
                outlined
                class="q-mr-sm width-180px"
              />
            </div>
            <div class="row q-my-sm width-400px">
              <span>{{ $t('status') }}</span>
              <q-space />
              <q-select
                v-model="sort_status"
                :options="sort_status_options_translated"
                :label="$t('status')"
                :clearable="true"
                @clear="clearStatus"
                dense
                outlined
                class="q-mr-sm width-180px"
              />
            </div>
            <div class="row q-my-sm width-400px">
              {{ $t('start_date') }}
              <q-space />
              <q-input
                outlined
                dense
                v-model="startDate"
                placeholder="YYYY-MM-DD"
                mask="####-##-##"
                data-cy="start_date"
                :clearable="true"
                class="q-mr-sm width-180px"
                @clear="clearDate('startDate')"
              >
                <template v-slot:append>
                  <q-icon
                    name="event"
                    class="cursor-pointer"
                    id="btn_start_date"
                  >
                    <q-popup-proxy>
                      <q-date
                        v-model="startDate"
                        mask="YYYY-MM-DD"
                        color="primary"
                      >
                        <q-btn
                          v-close-popup
                          :label="$t('close')"
                          color="primary"
                          flat
                        />
                      </q-date>
                    </q-popup-proxy>
                  </q-icon>
                </template>
              </q-input>
            </div>
            <div class="row q-my-sm width-400px">
              {{ $t('end_date') }}
              <q-space />
              <q-input
                outlined
                dense
                v-model="endDate"
                placeholder="YYYY-MM-DD"
                mask="####-##-##"
                data-cy="end_date"
                :clearable="true"
                class="q-mr-sm width-180px"
                @clear="clearDate('endDate')"
              >
                <template v-slot:append>
                  <q-icon name="event" class="cursor-pointer" id="btn_end_date">
                    <q-popup-proxy>
                      <q-date
                        v-model="endDate"
                        mask="YYYY-MM-DD"
                        color="primary"
                      >
                        <q-btn
                          v-close-popup
                          :label="$t('close')"
                          color="primary"
                          flat
                        />
                      </q-date>
                    </q-popup-proxy>
                  </q-icon>
                </template>
              </q-input>
            </div>
            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('apply')"
                @click="applyFilter"
              />
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="clearFilter"
              />
            </div>
          </q-menu>
        </template>
      </q-input>

      <div class="q-pa-md col-4 status-counter">
        <div class="row">
          <q-card
            flat
            bordered
            class="status-count-card status-count-card-primary"
          >
            <q-card-section class="status-count-number">
              {{ total_records ?? 0 }}
            </q-card-section>
            <q-tooltip>
              {{ $t('total') }}
            </q-tooltip>
          </q-card>
          <q-separator :vertical="true" class="seperator" />
          <q-card flat bordered class="status-count-card status-count-card-red">
            <q-card-section class="status-count-number">
              {{ in_error ?? 0 }}
            </q-card-section>
            <q-tooltip>
              {{ $t('wf_sort_status_error') }}
            </q-tooltip>
          </q-card>
          <q-card
            flat
            bordered
            class="status-count-card status-count-card-yellow"
          >
            <q-card-section class="status-count-number">
              {{ in_failed_condition ?? 0 }}
            </q-card-section>
            <q-tooltip>
              {{ $t('wf_sort_status_failed_condition') }}
            </q-tooltip>
          </q-card>
          <q-card
            flat
            bordered
            class="status-count-card status-count-card-green"
          >
            <q-card-section class="status-count-number">
              {{ in_success ?? 0 }}
            </q-card-section>
            <q-tooltip>
              {{ $t('wf_sort_status_success') }}
            </q-tooltip>
          </q-card>
        </div>
      </div>
      <q-space />

      <f-btn
        v-if="docOperatorVideoExists"
        class="docoperator-log-video-download"
        @click="downloadS3Video()"
        icon="file_download"
        :label="$t('wf_log_download_docoperator_log_video')"
      />

      <f-btn
        @click="$emit('closeWfLog')"
        appearance="flat"
        icon="close"
        class="justify-end"
      />
    </div>

    <div v-if="workflows_reached_limit.length > 0" class="wf-execution-limit-info">
      <q-card class="wf-execution-limit-info-card" flat bordered>
          <q-item>
            <q-item-section side>
              <Icon icon="mdi:alert" width="26" height="26" />
            </q-item-section>
            <q-item-section>
              {{ $t('wf_log_wf_execution_limit_reached', {'execution_limit': workflow_execution_limit}) }}
            </q-item-section>
          </q-item>
      </q-card>
    </div>

    <q-table
      class="workflow-table-style log-table-sticky"
      :class="[
        onDashboard ? 'log-table-height-dashboard' : 'log-table-height',
        { 'wf-table-uncapped': hasAdvancedExpanded },
      ]"
      flat
      bordered
      :rows="rows"
      :columns="columns"
      :rows-per-page-options="[page_size]"
      separator="cell"
      wrap-cells
      :virtual-scroll="true"
    >
      <template v-slot:pagination="">
        <q-pagination
          v-model="current_page"
          color="primary"
          :max="total_pages"
          class="q-py-xs q-mx-md"
          :max-pages="6"
          input
          boundary-links
          @update:model-value="nextPageClicked()"
        />
      </template>

      <template v-slot:header="props_logs_header">
        <q-tr :props="props_logs_header">
          <q-th
            v-for="col in props_logs_header.cols"
            :key="(col as any).name"
            :props="props_logs_header"
            :class="getHeaderColumnClass(col.name)"
          >
            <div class="wf-header-cell">
              <span class="wf-header-label">
                <template v-if="col.name === 'run_time_seconds'">
                  <q-icon name="timer" size="sm" class="header-icon">
                    <q-tooltip>{{ $t((col as any).label) }}</q-tooltip>
                  </q-icon>
                </template>
                <template v-else>
                  {{ $t((col as any).label) }}
                </template>
              </span>
              <span
                v-if="['wf_name', 'created_on'].includes(col.name)"
                class="col-order-by-anchor"
              >
                <ColumnOrderBy :column_name="col.name" />
              </span>
            </div>
          </q-th>
        </q-tr>
      </template>

      <template v-slot:body="props">
        <q-tr
          :props="props"
          @click="toggleLogRow(props)"
          class="cursor-pointer"
          :class="{ 'row-expanded': expandedRowKey === props.key }"
          :style="expandedRowKey === props.key ? expandedRowStyle : undefined"
        >
          <q-td
            v-for="col in props.cols"
            :key="(col as any).name"
            :props="props"
          >
            <span v-if="col.name === 'created_on'">
              {{ formatDateAccordingToPreference(col.value) }}
            </span>
            <span v-else-if="col.name === 'result'" class="result-column">
              <q-icon
                v-if="props.row[col.name] === 'success'"
                :name="'check_circle'"
                :color="'green'"
                size="sm"
              />
              <q-icon
                v-else-if="
                  props.row[col.name] === null ||
                  props.row[col.name] === 'failed_condition'
                "
                :name="'do_not_disturb_on'"
                :color="'orange'"
                size="sm"
              />
              <q-icon v-else :name="'cancel'" :color="'red'" size="sm" />
            </span>
            <span v-else-if="col.name === 'wf_name'">
              <div class="row items-center no-wrap full-width wf-name-cell">
                <q-icon
                  size="sm"
                  :name="props.expand ? 'keyboard_arrow_up' : 'keyboard_arrow_down'"
                  color="primary"
                  class="col-auto wf-name-chevron"
                />
                <div class="col workflow-name-text">{{ col.value }}</div>
                <q-icon
                  v-if="workflows_reached_limit.includes(props.row.workflow_id.toString())"
                  name="block"
                  size="sm"
                  color="red"
                  class="col-auto"
                >
                  <q-tooltip>
                    {{ $t('wf_log_workflow_reached_execution_limit') }}
                  </q-tooltip>
                </q-icon>
              </div>
            </span>
            <span v-else>
              {{ col.value }}
            </span>
          </q-td>
        </q-tr>
        <q-tr v-show="props.expand" :props="props">
          <q-td
            :colspan="
              props.row.workflow_name.includes('EXTERNAL_LOGS') ? '4' : '1'
            "
            class="no-padding workflow-content-column"
          >
            <div class="text-subtitle2 q-pa-md full-width">
              <div
                v-if="props.row.workflow_name.includes('EXTERNAL_LOGS')"
                class="small-heading"
              >
                <template v-for="(logs, index) in props.row.logs" :key="index">
                  <template v-for="log in logs" :key="log.id">
                    <div
                      class="q-my-sm row justify-between icon-grey card-message q-py-sm"
                    >
                      <div>
                        <Icon icon="mdi:message" width="20" height="20" class="q-mr-md" />
                        <span class="q-mr-md">{{ $t('message') }}:</span>
                      </div>
                      <span class="text-weight-regular">{{ log.message }}</span>
                    </div>
                    <q-separator />
                  </template>
                </template>
              </div>
              <!-- Workflow Flow Visualization (v3 workflows) -->
              <div
                v-else-if="props.row.workflow_version === 3 && hasWorkflowData(props.row)"
                class="workflow-flow-container"
              >
                <AdvancedWorkflowViewer
                  v-if="getTransformedWorkflowData(props.row)"
                  :nodes="getTransformedWorkflowData(props.row).nodes"
                  :edges="getTransformedWorkflowData(props.row).edges"
                  :executionData="getTransformedWorkflowData(props.row).executionData"
                  :selectedNodeId="selectedAdvancedNodeId"
                  :readOnly="true"
                  :zoomEnabled="true"
                  :panEnabled="true"
                  :showBackground="true"
                  :showMinimap="false"
                  :nodes-draggable="true"
                  @node-click="(nodeId: string) => getAdvancedWorkflowNodeLogs(props.row, nodeId)"
                />
              </div>
              <div
                v-else-if="
                  ![undefined, null].includes(
                    (props.row as any).workflow_data,
                  ) &&
                  (props.row as any).workflow_data != undefined &&
                  (props.row as any).workflow_data.when_condition.card_logs !=
                    undefined
                "
              >
                <span class="card-category-text">{{ $t('wf_when') }}</span>
                <div class="full-width">
                  <div>
                    <GenericCard
                      :card_result="
                        checkCardSuccess((props.row as any).id, 0, 'when')
                      "
                      :item="(props.row as any).workflow_data.when_condition"
                      :version="
                        (props.row as any).workflow_data.when_condition.version
                      "
                      @click="
                        getCardLogs(
                          (props.row as any).workflow_data.when_condition.id,
                          (props.row as any).id,
                          0,
                          'when',
                        )
                      "
                    />
                  </div>
                </div>

                <div
                  v-if="
                    !props.row.workflow_version ||
                    props.row.workflow_version == 1
                  "
                >
                  <div class="card-category-text">{{ $t('wf_and') }}</div>
                  <div
                    class="full-width"
                    v-for="(item, index) in (props.row as any).workflow_data
                      .and_conditions"
                    :key="item.id + '_' + item.card_version + '_' + index"
                  >
                    <div>
                      <GenericCard
                        :card_result="
                          checkCardSuccess((props.row as any).id, index, 'and')
                        "
                        :item="item"
                        :version="item.version"
                        @click="
                          getCardLogs(
                            item.id,
                            (props.row as any).id,
                            index,
                            'and',
                          )
                        "
                      />
                    </div>
                  </div>

                  <div class="card-category-text">{{ $t('wf_then') }}</div>
                  <div
                    class="full-width"
                    v-for="(item, index) in (props.row as any).workflow_data
                      .then_conditions"
                    :key="item.id + '_' + item.card_version + '_' + index"
                  >
                    <div>
                      <GenericCard
                        :card_result="
                          checkCardSuccess((props.row as any).id, index, 'then')
                        "
                        :item="item"
                        :version="item.version"
                        @click="
                          getCardLogs(
                            item.id,
                            (props.row as any).id,
                            index,
                            'then',
                          )
                        "
                      />
                    </div>
                  </div>
                </div>
                <!-- <div v-else-if="props.row.workflow_version == 2"> -->
                <div v-else>
                  <div class="card-category-text">{{ $t('wf_and') }}</div>
                  <div
                    class="full-width"
                    v-for="(item, index) in (props.row as any).workflow_data
                      .and_conditions"
                    :key="item.id + '_' + item.card_version + '_' + index"
                  >
                    <div
                      v-if="
                        props.row.workflow_data.and_condition_break == null ||
                        index <= props.row.workflow_data.and_condition_break
                      "
                    >
                      <GenericCard
                        :card_result="
                          checkCardSuccess((props.row as any).id, index, 'and')
                        "
                        :item="item"
                        :version="item.version"
                        @click="
                          getCardLogs(
                            item.id,
                            (props.row as any).id,
                            index,
                            'and',
                          )
                        "
                      />
                    </div>
                  </div>
                  <div>
                    <q-markup-table
                      :separator="'none'"
                      wrap-cells
                      flat
                      square
                      class="markup-table-branching"
                      v-if="props.row.workflow_version == 2"
                    >
                      <tbody>
                        <tr>
                          <td>
                            <div class="card-category-text">
                              {{ $t('wf_and_continued') }}
                            </div>
                            <template
                              v-for="(item, index) in props.row.workflow_data
                                .and_conditions"
                              :key="
                                item.id +
                                '_' +
                                item.card_version +
                                '_' +
                                item.uuid
                              "
                            >
                              <div
                                v-if="
                                  props.row.workflow_data.and_condition_break !=
                                    null &&
                                  index >
                                    props.row.workflow_data.and_condition_break
                                "
                              >
                                <GenericCard
                                  :card_result="
                                    checkCardSuccess(
                                      (props.row as any).id,
                                      index,
                                      'and',
                                    )
                                  "
                                  :item="item"
                                  :version="item.version"
                                  @click="
                                    getCardLogs(
                                      item.id,
                                      (props.row as any).id,
                                      index,
                                      'and',
                                    )
                                  "
                                />
                              </div>
                            </template>

                            <div class="card-category-text">
                              {{ $t('wf_then') }}
                            </div>
                            <template
                              v-for="(item, index) in props.row.workflow_data
                                .then_conditions"
                              :key="
                                item.id +
                                '_' +
                                item.card_version +
                                '_' +
                                item.uuid
                              "
                            >
                              <div class="selected-card">
                                <GenericCard
                                  :card_result="
                                    checkCardSuccess(
                                      (props.row as any).id,
                                      index,
                                      'then',
                                    )
                                  "
                                  :item="item"
                                  :version="item.version"
                                  @click="
                                    getCardLogs(
                                      item.id,
                                      (props.row as any).id,
                                      index,
                                      'then',
                                    )
                                  "
                                />
                              </div>
                            </template>
                          </td>
                          <td
                            v-for="(
                              itemAdditionalCondition, indexAdditionals
                            ) in props.row.workflow_data
                              .additional_and_conditions"
                            :key="indexAdditionals"
                          >
                            <div class="card-category-text">
                              {{
                                props.row.workflow_data
                                  .additional_and_conditions.length ==
                                  (indexAdditionals as number) + 1 &&
                                props.row.workflow_data
                                  .additional_and_conditions[indexAdditionals]
                                  .length == 0
                                  ? $t('wf_alternate_conditions_else')
                                  : $t('wf_alternate_conditions')
                              }}
                            </div>
                            <template
                              v-for="(item, index) in props.row.workflow_data
                                .additional_and_conditions[indexAdditionals]"
                              :key="
                                item.id +
                                '_' +
                                item.card_version +
                                '_' +
                                item.uuid
                              "
                            >
                              <div class="selected-card">
                                {{ item.indexAdditionals }}
                                <GenericCard
                                  :card_result="
                                    checkCardSuccess(
                                      (props.row as any).id,
                                      index,
                                      'additional_conditions',
                                      (indexAdditionals as number),
                                    )
                                  "
                                  :item="item"
                                  :version="item.version"
                                  @click="
                                    getCardLogs(
                                      item.id,
                                      (props.row as any).id,
                                      index,
                                      'additional_conditions',
                                      (indexAdditionals as number),
                                    )
                                  "
                                />
                              </div>
                            </template>
                            <div class="card-category-text">
                              {{ $t('wf_alternate_executions') }}
                            </div>
                            <template
                              v-for="(item, index) in props.row.workflow_data
                                .additional_then_executions[indexAdditionals]"
                              :key="
                                item.id +
                                '_' +
                                item.card_version +
                                '_' +
                                item.uuid
                              "
                            >
                              <div class="selected-card">
                                {{ item.indexAdditionals }}
                                <GenericCard
                                  :card_result="
                                    checkCardSuccess(
                                      (props.row as any).id,
                                      index,
                                      'additional_executions',
                                      (indexAdditionals as number),
                                    )
                                  "
                                  :item="item"
                                  :version="item.version"
                                  @click="
                                    getCardLogs(
                                      item.id,
                                      (props.row as any).id,
                                      index,
                                      'additional_executions',
                                      (indexAdditionals as number),
                                    )
                                  "
                                />
                              </div>
                            </template>
                          </td>
                        </tr>
                      </tbody>
                    </q-markup-table>
                  </div>
                </div>
              </div>

              <div v-else>
                <div
                  v-if="workflowChanged((props.row as any).id)"
                  class="small-heading"
                >
                  {{ $t('wf_workflow_changed') }}
                </div>

                <div>
                  <div class="card-category-text">{{ $t('wf_when') }}</div>
                </div>
                <div
                  class="full-width"
                  v-if="
                    Object.keys(workflows).includes(
                      (props.row as any).workflow_id,
                    )
                  "
                >
                  <div>
                    <GenericCard
                      :card_result="
                        checkCardSuccess((props.row as any).id, 0, 'when')
                      "
                      :item="
                        workflows[(props.row as any).workflow_id]!
                          .when_condition
                      "
                      :version="
                        workflows[(props.row as any).workflow_id]!
                          .when_condition.version
                      "
                      @click="
                        getCardLogs(
                          workflows[(props.row as any).workflow_id]
                            .when_condition.id,
                          (props.row as any).id,
                          0,
                          'when',
                        )
                      "
                    />
                  </div>
                </div>

                <div>
                  <div class="card-category-text">{{ $t('wf_and') }}</div>
                </div>
                <div
                  class="full-width"
                  v-for="(item, index) in workflows[
                    (props.row as any).workflow_id
                  ].and_conditions"
                  :key="item.id + '_' + item.card_version + '_' + index"
                >
                  <div>
                    <GenericCard
                      :card_result="
                        checkCardSuccess((props.row as any).id, index, 'and')
                      "
                      :item="item"
                      :version="item.version"
                      @click="
                        getCardLogs(
                          item.id,
                          (props.row as any).id,
                          index,
                          'and',
                        )
                      "
                    />
                  </div>
                </div>

                <div>
                  <div class="card-category-text">{{ $t('wf_then') }}</div>
                </div>
                <div
                  class="full-width"
                  v-for="(item, index) in workflows[
                    (props.row as any).workflow_id
                  ].then_conditions"
                  :key="item.id + '_' + item.card_version + '_' + index"
                >
                  <div>
                    <GenericCard
                      :card_result="
                        checkCardSuccess((props.row as any).id, index, 'then')
                      "
                      :item="item"
                      :version="item.version"
                      @click="
                        getCardLogs(
                          item.id,
                          (props.row as any).id,
                          index,
                          'then',
                        )
                      "
                    />
                  </div>
                </div>
              </div>
            </div>
          </q-td>
          <q-td
            v-if="!props.row.workflow_name.includes('EXTERNAL_LOGS')"
            colspan="3"
            class="no-padding log-message-column"
          >
            <div class="q-pa-md">
              <div class="small-heading">
                <div
                  v-if="
                    props.row.workflow_version === 3 ||
                    (![undefined, null].includes(
                      (props.row as any).workflow_data,
                    ) &&
                      (props.row as any).workflow_data != undefined &&
                      (props.row as any).workflow_data.when_condition &&
                      ![undefined, null].includes(
                        (props.row as any).workflow_data.when_condition
                          .card_logs,
                      )) ||
                    !workflowChanged((props.row as any).id)
                  "
                >
                  {{ $t('wf_card_logs') }}
                </div>
                <div v-else>
                  {{ $t('wf_workflow_logs') }}
                </div>
              </div>
              <div
                v-if="displayed_messages[(props.row as any).id]"
              >
                <div
                  v-for="(message, index) in displayed_messages[
                    (props.row as any).id
                  ]"
                  :key="index"
                >
                  <span
                    v-if="message.translation_key"
                    class="card-message"
                    >{{
                      $t(
                        'wf_log_' + message.translation_key,
                        translateDataLocal(message.data),
                      )
                    }}</span
                  >
                  <span v-else class="card-message">{{
                    message.message
                  }}</span>
                </div>
              </div>
              <div v-else>
                {{ $t('wf_card_logs_message') }}
              </div>
            </div>
          </q-td>
        </q-tr>
      </template>
    </q-table>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import GenericCard from 'src/pages/WorkflowBuilder/workflowLogs/generic_card_logs.vue';
import AdvancedWorkflowViewer from 'src/pages/WorkflowBuilder/WorkflowComponnets/AdvancedWorkflowViewer.vue';
import { useWorkflowLogTransformation } from 'src/pages/WorkflowBuilder/composables/useWorkflowLogTransformation';
import { buildNodeLogMessage } from 'src/pages/WorkflowBuilder/composables/useNodeLogMessage';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { workflowApiService, documentDetailApiService } from 'src/services';
import { dynamicObj } from '../../assets';
import { date } from 'quasar';
import { storeToRefs } from 'pinia';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';
import dateUtils from 'src/utils/date';
import { i18n } from 'src/boot/i18n';
import { useDropdownStore, useWorkflowBuilderStore } from 'src/store/main';
import ColumnOrderBy from './column-orderBy.vue';
import { CONSTANTS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import { populateWorkflowModelForCard, maskSensitiveCardVariables } from 'src/pages/WorkflowBuilder/composables/useCardVariableResolver';

export interface SortBy {
  value: string;
  label: string;
}

export default defineComponent({
  name: 'WorkflowLogs',
  mixins: [helperUtil, helperMixin, dateUtils],
  components: {  Loader, GenericCard, SubHeader, ColumnOrderBy, AdvancedWorkflowViewer },
  emits: ['closeWfLog'],
  props: {
    onDashboard: {
      type: Boolean,
      default: false,
    },
    doc_id: {
      type: String,
      default: '',
    },
  },
  computed: {
    hasAdvancedExpanded(): boolean {
      if (this.expandedRowKey == null) return false;
      const expanded =
        this.rows.find((r: any) => r.id === this.expandedRowKey) ??
        this.rows[this.expandedRowKey as any];
      if (!expanded) return false;
      return expanded.workflow_version === 3 && this.hasWorkflowData(expanded);
    },
  },
  watch: {
    async doc_id() {
      if (!this.doc_id) {
        return;
      }
      this.docId = this.doc_id;
      this.docOperatorVideoExists = false;
      if (this.order_by) {
        ColumnOrderBy.methods?.resetSelectedClass(
          this.order_by.field_name,
          this.order_by.direction,
        );
        ColumnOrderBy.methods?.addSelectedClass(
          this.order_by.field_name,
          this.order_by.direction,
        );
        this.sort_by = this.getSortByValue(this.order_by.field_name);
        this.sort_direction = this.getSortDirectionValue(
          this.order_by.direction,
        );
      }
      await this.resetData();
      await this.loadInitialData();
      await this.check_S3_for_video();
    },
  },
  data() {
    return {
      docId: '',
      initialDataLoaded: false,
      docOperatorVideoExists: false,
      docOperatorVideoFormat: '.webm',
      // Cache for transformed workflow data to prevent reactive loops
      transformedWorkflowCache: {} as Record<string, any>,
      // Maximum number of cache entries before eviction (prevents memory leaks)
      CACHE_SIZE_LIMIT: 50,
    };
  },

  async mounted() {
    if (!this.order_by) {
      this.resetOrderBy();
    }
    this.docId = this.onDashboard
      ? this.doc_id
      : this.$route.params.id.toString();
    this.loadInitialData();
    document.addEventListener('wf_apply_filters', this.applyFilterEvent);
    await this.check_S3_for_video();
    (<any>window).vLog = this;
  },

  async unmounted() {
    document.removeEventListener('wf_apply_filters', this.applyFilterEvent);
    this.docOperatorVideoExists = false;
    await this.clearFilter(false);
    await this.clearSearchValue(false);
  },

  methods: {
    toggleLogRow(props: any) {
      const wasExpanded = props.expand;
      props.expand = !wasExpanded;
      this.expandedRowKey = !wasExpanded ? props.key : null;
    },
    /**
     * Check if log entry has workflow data for visualization
     */
    hasWorkflowData(logEntry: any): boolean {
      return (
        logEntry.workflow_version === 3 &&
        logEntry.workflow_data?.nodes?.length > 0
      );
    },

    /**
     * Populate workflowModel store with saved variable values for log viewing
     */
    /**
     * Populate workflowModel with properly resolved variable values for log viewing.
     * Delegates to the shared populateWorkflowModelForCard which resolves script IDs
     * to names, translates operators, etc. via getVariableData.
     * Uses a log-entry prefix so multiple expanded rows don't overwrite each other.
     */
    populateWorkflowModelForLogs(logEntry: any) {
      if (!logEntry.workflow_data?.nodes) {
        return;
      }

      const logPrefix = logEntry.id != null ? `log_${logEntry.id}_` : '';

      logEntry.workflow_data.nodes.forEach((node: any) => {
        if (!node.card) {
          return;
        }
        maskSensitiveCardVariables(node.card);
        populateWorkflowModelForCard(node.card, logPrefix);
      });
    },

    /**
     * Transform log entry to VueFlow format for visualization
     */
    getTransformedWorkflowData(logEntry: any) {
      if (!this.hasWorkflowData(logEntry)) {
        return null;
      }

      const cacheKey = logEntry.id?.toString();

      // Always populate workflowModel — populateWorkflowModelForCard handles
      // idempotency via _resolved flag. Re-running is needed because dropdown
      // data (prompts, users, etc.) may load after the first render.
      this.populateWorkflowModelForLogs(logEntry);

      // Return cached transformation if available
      if (cacheKey && this.transformedWorkflowCache[cacheKey]) {
        return this.transformedWorkflowCache[cacheKey];
      }

      try {
        const result = this.transformWorkflowLog(logEntry);

        // Cache the result to prevent repeated transformation calls
        if (cacheKey) {
          // Evict old cache entries if limit exceeded (prevents memory leaks)
          const cacheKeys = Object.keys(this.transformedWorkflowCache);
          if (cacheKeys.length > this.CACHE_SIZE_LIMIT * 2) {
            // Remove oldest entries (keep recent ones)
            const keysToRemove = cacheKeys.slice(0, cacheKeys.length - this.CACHE_SIZE_LIMIT);
            keysToRemove.forEach(key => delete this.transformedWorkflowCache[key]);
          }

          this.transformedWorkflowCache[cacheKey] = result;
        }

        return result;
      } catch (error) {
        logError(`Failed to transform workflow log ${cacheKey}:`, error);
        return null;
      }
    },

    /**
     * Get logs for a specific node in an advanced (v3) workflow
     */
    getAdvancedWorkflowNodeLogs(logEntry: any, nodeId: string) {
      if (!logEntry) {
        return;
      }

      // Track selected node for highlighting
      this.selectedAdvancedNodeId = nodeId;

      const workflowRunId = logEntry.id.toString();

      const locale = useDropdownStore().getSelectedLanguage();

      // Try to get card_logs from workflow_data.nodes (same format as v1/v2 card_logs)
      if (logEntry.workflow_data?.nodes) {
        const wfNode = logEntry.workflow_data.nodes.find((n: any) => n.node_id === nodeId);
        if (wfNode?.card?.card_logs && wfNode.card.card_logs.length > 0) {
          const partnerTranslations = wfNode.card.partner_translations ?? null;
          this.displayed_messages[workflowRunId] = wfNode.card.card_logs.map((log: any) =>
            buildNodeLogMessage(log, partnerTranslations, locale),
          );
          return;
        }
        // For cardless nodes (ALL/ANY/DELAY), use node-level logs
        if (wfNode?.logs && wfNode.logs.length > 0) {
          this.displayed_messages[workflowRunId] = wfNode.logs.map((log: any) =>
            buildNodeLogMessage(log),
          );
          return;
        }
      }

      // Fallback: check top-level execution logs
      if (logEntry.logs) {
        const flatLogs = logEntry.logs.flat();
        const nodeLog = flatLogs.find((log: any) => log && log.node_id === nodeId);
        if (nodeLog?.logs && nodeLog.logs.length > 0) {
          const partnerTranslations = nodeLog.partner_translations ?? null;
          this.displayed_messages[workflowRunId] = nodeLog.logs.map((log: any) =>
            buildNodeLogMessage(log, partnerTranslations, locale),
          );
          return;
        }
        // Show status if no detailed logs
        if (nodeLog) {
          const statusKey = `wf_sort_status_${nodeLog.status}`;
          const statusLabel = i18n.t(statusKey, { defaultValue: nodeLog.status });
          this.displayed_messages[workflowRunId] = [{ message: statusLabel }];
          return;
        }
      }

      // Node was not executed
      this.displayed_messages[workflowRunId] = [{ message: i18n.t('wf_skipped') }];
    },

    applyFilterEvent(e: any) {
      if (e && e.detail) {
        this.resetPagination();
        this.sort_by = this.getSortByValue(this.order_by.field_name);
        this.sort_direction = this.getSortDirectionValue(
          this.order_by.direction,
        );
        this.applyFilter();
      }
    },
    resetOrderBy(field_name = 'created_on', direction = 'desc') {
      // direction: desc || asc
      // field_name: column to filter by, created_on, wf_name
      this.order_by = { field_name: field_name, direction: direction };
    },

    async loadInitialData() {
      if (!this.docId) {
        return;
      }

      await this.getLogsForDocument();
      if (this.initialDataLoaded) {
        return;
      }
      // Set the flag to prevent future executions
      this.initialDataLoaded = true;

      // Load card catalogs so populateWorkflowModelForCard can merge template
      // variable IDs (fixes badge position bug when backend returns variables
      // in a different order than the card template defines).
      const wfBuilderStore = useWorkflowBuilderStore();
      wfBuilderStore.getWorkflowAllCards();
      wfBuilderStore.loadWorkflowVariables();
      this.translateSortOptions();

      await Promise.allSettled([
        this.getUsers(),
        this.getGroups(),
        this.getWorkflows(),
        this.getDecisionTables(),
        this.getDocOperatorPrompts(),
        this.prepareEmailTemplateDropdown(),
      ]);
      this.notifyInitErrorsIfAny();
    },

    formatDate(strDate: string, dateFormat: string) {
      return date.formatDate(strDate, dateFormat);
    },
    async check_S3_for_video(): Promise<boolean> {
      if (this.docId) {
        this.docOperatorVideoExists = await documentDetailApiService.checkS3(
          this.docId,
          this.docId + this.docOperatorVideoFormat,
        );
      } else {
        this.docOperatorVideoExists = false;
      }
      return this.docOperatorVideoExists;
    },

    async downloadS3Video() {
      try {
        this.showLoading();
        // only one video with name as id of document exists for docoperator logs
        const link = document.createElement('a');
        link.href = await documentDetailApiService.get_S3_file_download_url(
          this.docId + this.docOperatorVideoFormat,
          'documents/' + this.docId + '/' + this.docId + this.docOperatorVideoFormat,
        );
        link.download = this.docId + this.docOperatorVideoFormat;
        link.click();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    prepareTableRows() {
      this.rows = this.logs;
      for (let i = 0; i < this.rows.length; i++) {
        this.rows[i].name = this.rows[i].workflow_name;
        this.rows[i].created_on = this.rows[i].created_on;
        this.rows[i].run_time_seconds = (
          this.rows[i].run_time_mili_seconds / 1000
        ).toFixed(2);
      }
    },

    async nextPageClicked() {
      try {
        this.showLoading();
        this.displayed_messages = {};
        this.card_messages = {};
        this.transformedWorkflowCache = {};
        this.workflows = {};
        this.calculateOffset();
        await this.getLogsForDocument();
      } catch (err: any) {
        notify.error(err);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    resetPagination() {
      this.total_pages = 0;
      this.current_page = 1;
      this.total_records = 0;
      this.offset = 0;
    },

    setTotalPages() {
      this.total_pages = Math.ceil(this.total_records / this.page_size);
    },

    calculateOffset() {
      this.offset = this.page_size * (this.current_page - 1);
    },

    async inputSearchValueChanges(new_search_value: string) {
      try {
        this.showLoading();
        this.resetPagination();
        this.search_value = new_search_value;
        await this.getLogsForDocument();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async clearSearchValue(reload = true) {
      this.search_value = '';
      if (reload) {
        await this.getLogsForDocument();
      }
    },

    async clearFilter(reload = true) {
      if (!reload) {
        // required for sort_direction / sort_by
        this.resetOrderBy();
      }
      this.sort_direction = this.getSortDirectionValue(this.order_by.direction);
      this.sort_by = this.getSortByValue(this.order_by.field_name);
      this.sort_status = { value: '', label: i18n.t('') };
      this.startDate = '';
      this.endDate = '';
      if (reload) {
        // requires previous resets
        await this.getLogsForDocument();
      }
    },

    getSortByValue(value: string): SortBy {
      // default values required for initial loading
      if (value) {
        if (value == 'created_on') {
          return this.sort_filters_stored['created_on']
            ? (this.sort_filters_stored['created_on'] as SortBy)
            : ({
                value: 'created_on',
                label: i18n.t('log_created_on'),
              } as SortBy);
        }
        if (value == 'wf_name') {
          return this.sort_filters_stored['wf_name']
            ? (this.sort_filters_stored['wf_name'] as SortBy)
            : ({ value: 'wf_name', label: i18n.t('wf_name') } as SortBy);
        }
      }
      return this.sort_filters_stored['created_on']
        ? (this.sort_filters_stored['created_on'] as SortBy)
        : ({ value: 'created_on', label: i18n.t('log_created_on') } as SortBy);
    },

    getSortDirectionValue(value: string): SortBy {
      // default values required for initial loading
      if (value) {
        if (value.includes('desc')) {
          return this.sort_filters_stored['desc']
            ? (this.sort_filters_stored['desc'] as SortBy)
            : ({ value: 'desc', label: i18n.t('sort_desc') } as SortBy);
        }
        if (value.includes('asc')) {
          return this.sort_filters_stored['asc']
            ? (this.sort_filters_stored['asc'] as SortBy)
            : ({ value: 'asc', label: i18n.t('sort_asc') } as SortBy);
        }
      }
      return this.sort_filters_stored['desc']
        ? (this.sort_filters_stored['desc'] as SortBy)
        : ({ value: 'desc', label: i18n.t('sort_desc') } as SortBy);
    },

    clearStatus() {
      this.sort_status = { value: '', label: i18n.t('') };
    },

    clearDate(date: string) {
      if (date === 'startDate') {
        this.startDate = '';
      } else if (date === 'endDate') {
        this.endDate = '';
      } else {
        this.startDate = '';
        this.endDate = '';
      }
    },
    async applyFilter() {
      this.resetOrderBy(this.sort_by.value, this.sort_direction.value);
      this.resetPagination();
      await this.getLogsForDocument();
    },

    async getLogsForDocument() {
      try {
        this.showLoading();
        let formdata = {} as dynamicObj;
        formdata['per_site'] = this.page_size;
        formdata['offset'] = this.offset;
        formdata['sort_direction'] = this.sort_direction.value;
        formdata['sort_by'] = this.sort_by.value;
        if (this.sort_status.value.length > 1) {
          formdata['status'] = this.sort_status.value.replace(
            'sort_status_',
            '',
          );
        }
        if (this.search_value.length > 0) {
          formdata['keyword'] = this.search_value;
        }
        if (this.startDate.length > 1) {
          formdata['start_date'] = this.startDate;
        }
        if (this.endDate.length > 1) {
          formdata['end_date'] = this.endDate;
        }

        this.wf_logs = await workflowApiService.getWorkflowLogsForDoc(
          this.docId,
          formdata,
        );
        this.logs = this.wf_logs.logs;
        this.complete_logs = this.wf_logs;
        this.total_records = this.wf_logs.total;
        this.in_error = this.wf_logs.in_status.in_error;
        this.in_failed_condition = this.wf_logs.in_status.in_failed_condition;
        this.in_success = this.wf_logs.in_status.in_success;
        this.workflow_execution_limit = this.wf_logs.workflow_execution_limit;
        this.workflows_reached_limit = this.wf_logs.workflows_reached_limit;
        this.setTotalPages();
        for (let log of this.wf_logs.logs) {
          this.loadWorkflow(log.workflow_id);
        }
        this.prepareTableRows();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    async resetData(reload = false) {
      this.resetPagination();
      this.logs = [];
      this.workflows = {};
      this.complete_logs = {};
      this.card_messages = {};
      this.displayed_messages = {};
      this.wf_logs = {};
      this.rows = [];
      this.in_error = null;
      this.in_success = null;
      this.in_failed_condition = null;
      this.transformedWorkflowCache = {};
      await this.clearFilter(reload);
      await this.clearSearchValue(reload);
    },

    loadWorkflow(wf_id: string) {
      if (
        !Object.keys(this.workflows).includes(wf_id) &&
        Object.keys(this.complete_logs.workflows).includes(wf_id)
      ) {
        let wf = this.complete_logs.workflows[wf_id];
        this.workflows[wf_id] = wf;
        let date_str = '';
        if (wf.last_modified_on != null) {
          date_str = wf.last_modified_on;
        } else {
          date_str = wf.created_on;
        }
        this.workflows[wf_id].last_modified_on = date_str;
      }
    },

    getCardLogs(
      card_id: string,
      workflow_run_id: string,
      index: any,
      run_category: string,
      indexAdditionals = 0,
    ) {
      if (
        !Object.keys(this.card_messages).includes(
          card_id.toString() +
            workflow_run_id.toString() +
            index +
            '_' +
            run_category,
        )
      ) {
        this.prepareCardLogs(card_id, workflow_run_id, index, run_category);
      }
      const log_key =
        card_id.toString() +
        workflow_run_id.toString() +
        index +
        '_' +
        run_category;
      this.displayed_messages[workflow_run_id.toString()] = ![
        CONSTANTS.additional_conditions,
        CONSTANTS.additional_executions,
      ].includes(run_category)
        ? this.card_messages[log_key]
        : this.card_messages[log_key + indexAdditionals];
    },

    translateDataLocal(data: dynamicObj) {
      return this.translateData(data);
    },

    prepareCardLogs(
      card_id: string,
      workflow_run_id: string,
      index: any,
      run_category: string,
    ) {
      const workflow_log = this.getWorkflowRunLog(workflow_run_id);
      const full_workflow_log = this.getFullWorkflowLog(workflow_run_id);
      return this.workflowprepareCardLogs(
        full_workflow_log,
        workflow_log,
        card_id,
        workflow_run_id,
        index,
        run_category,
      );
    },

    prepareCompleteLogs(workflow_run_id: string) {
      const workflow_log = this.getWorkflowRunLog(workflow_run_id);
      let workflow_run_log = [];
      for (let log of workflow_log) {
        for (let log_msg of log) {
          workflow_run_log.push(log_msg);
        }
      }
      this.displayed_messages[workflow_run_id.toString()] = workflow_run_log;
    },

    checkCardSuccess(
      workflow_run_id: string,
      index: any,
      run_category: string,
      indexAdditionals = 0,
    ) {
      try {
        const workflow_log = this.getWorkflowRunLog(workflow_run_id);
        const full_workflow_log = this.getFullWorkflowLog(workflow_run_id);
        return this.checkLogSuccessCards(
          full_workflow_log,
          workflow_log,
          run_category,
          index,
          indexAdditionals,
        );
      } catch (err) {
        logError(err);
      }
    },

    getWorkflowRunLog(workflow_run_id: string) {
      let wfr_log = '';
      for (let log of this.logs) {
        if (log.id == workflow_run_id) {
          wfr_log = log.logs;
          return wfr_log;
        }
      }
      return wfr_log;
    },

    getFullWorkflowLog(workflow_run_id: string) {
      let wfr_log = '';
      for (let log of this.logs) {
        if (log.id == workflow_run_id) {
          wfr_log = log;
        }
      }
      return wfr_log;
    },

    getHeaderColumnClass(colName: string): string {
      if (colName === 'wf_name') {
        return 'header-col-workflow';
      }
      const modifier =
        colName === 'created_on'
          ? 'col-created-on'
          : colName === 'run_time_seconds'
            ? 'col-runtime'
            : colName === 'result'
              ? 'col-result'
              : '';
      return `header-col-logs ${modifier}`.trim();
    },

    workflowChanged(workflow_run_id: string) {
      let wf_changed = false;
      for (let wf_log of this.logs) {
        if (
          wf_log.id == workflow_run_id &&
          Object.keys(this.workflows).includes(wf_log.workflow_id)
        ) {
          wf_changed =
            new Date(JSON.parse(JSON.stringify(wf_log.created_on))).getTime() <
            new Date(
              JSON.parse(
                JSON.stringify(
                  this.workflows[wf_log.workflow_id].last_modified_on,
                ),
              ),
            ).getTime();

          if (wf_changed) {
            this.prepareCompleteLogs(workflow_run_id);
          }
          return wf_changed;
        } else if (wf_log.id == workflow_run_id) {
          return false;
        }
      }

      return wf_changed;
    },

    translateSortOptions() {
      for (let value of this.sort_by_options) {
        if (value === 'created_on') {
          const sort_option = {
            value: value,
            label: i18n.t('log_' + value),
          };
          this.sort_by_options_translated.push(sort_option);
          this.sort_filters_stored[value] = sort_option;
        } else {
          const sort_option = {
            value: value,
            label: i18n.t(value),
          };
          this.sort_by_options_translated.push(sort_option);
          this.sort_filters_stored[value] = sort_option;
        }
      }
      this.sort_by = this.getSortByValue('created_on');
      for (let value of this.sort_direction_options) {
        const sort_option = {
          value: value,
          label: i18n.t('sort_' + value),
        };
        this.sort_direction_options_translated.push(sort_option);
        this.sort_filters_stored[value] = sort_option;
      }
      this.sort_direction = this.getSortDirectionValue('desc');
      for (let value of this.sort_status_options) {
        const sort_option = {
          value: value,
          label: i18n.t(value),
        };
        this.sort_status_options_translated.push(sort_option);
        this.sort_filters_stored[value] = sort_option;
      }
      this.clearStatus();
    },

  },
  setup() {
    const columns = [
      {
        name: 'wf_name',
        required: true,
        label: 'wf_name',
        align: 'left' as const,
        field: 'workflow_name',
        headerClasses: 'table-header-wf-logs',
        classes: 'col-workflow',
      },
      {
        name: 'created_on',
        required: false,
        label: 'log_created_on',
        align: 'left' as const,
        field: 'created_on',
        headerClasses: 'table-header-wf-logs',
        classes: 'col-logs col-created-on',
      },
      {
        name: 'run_time_seconds',
        required: false,
        label: 'run_time_seconds',
        align: 'right' as const,
        field: 'run_time_seconds',
        headerClasses: 'table-header-wf-logs',
        classes: 'col-logs col-runtime',
      },
      {
        name: 'result',
        required: false,
        label: 'result',
        align: 'center' as const,
        field: 'result',
        headerClasses: 'table-header-wf-logs',
        classes: 'col-logs col-result',
      },
    ];

    const workflowVariableStore = useWorkflowLogsVariablesStore();
    const {
      getUsers,
      getGroups,
      getWorkflows,
      getDecisionTables,
      getDocOperatorPrompts,
      notifyInitErrorsIfAny,
      checkLogSuccessCards,
      workflowprepareCardLogs,
      translateData,
    } = workflowVariableStore;
    const { logs, wf_logs, card_messages, order_by } = storeToRefs(
      workflowVariableStore,
    );

    const dropdown_store = useDropdownStore();
    const { prepareEmailTemplateDropdown } = dropdown_store;

    // Workflow builder store for variable badges
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(workflow_builder_store);

    // Workflow log transformation composable
    const { transformWorkflowLog } = useWorkflowLogTransformation();

    return {
      transformWorkflowLog,
      workflowModel,
      workflows: ref({} as dynamicObj),
      complete_logs: ref({} as dynamicObj),
      displayed_messages: ref({} as dynamicObj),
      columns,
      rows: ref([] as any),
      logs,
      wf_logs,
      card_messages,
      order_by, // from event, stored for filter on columns, sort_by is used for actual api call
      getUsers,
      getGroups,
      getWorkflows,
      getDecisionTables,
      getDocOperatorPrompts,
      notifyInitErrorsIfAny,
      checkLogSuccessCards,
      workflowprepareCardLogs,
      prepareEmailTemplateDropdown,
      translateData,
      current_page: ref(1),
      total_pages: ref(0),
      offset: ref(0),
      page_size: ref(10),
      total_records: ref(0),

      search_value: ref(''),
      startDate: ref(''),
      endDate: ref(''),
      sort_direction: ref({ value: 'desc', label: 'desc' } as SortBy),
      sort_direction_options: ['desc', 'asc'],
      sort_direction_options_translated: ref([] as any),
      sort_by: ref({ value: 'created_on', label: 'log_created_on' } as SortBy),
      sort_by_options: ['created_on', 'wf_name'],
      sort_by_options_translated: ref([] as any),
      sort_filters_stored: ref({} as dynamicObj),
      sort_status: ref({ value: '', label: '' }),
      sort_status_options: [
        'sort_status_success',
        'sort_status_failed_condition',
        'sort_status_error',
      ],
      sort_status_options_translated: ref([] as any),

      in_error: ref(null),
      in_success: ref(null),
      in_failed_condition: ref(null),
      workflow_execution_limit: ref(30 as number),
      workflows_reached_limit: ref([] as string[]),
      selectedAdvancedNodeId: ref<string | null>(null),
      expandedRowKey: ref<string | null>(null),
      expandedRowStyle: {
        background: 'color-mix(in srgb, var(--primary) 30%, var(--background))',
        boxShadow: 'inset 3px 0 0 0 var(--primary)',
      },
    };
  },
});
