/**
 * Composable for transforming workflow execution log data into VueFlow format.
 *
 * Transforms version 3 (advanced) workflow logs with nodes/edges into a format
 * suitable for visual display using VueFlow components.
 */

import { computed, Ref } from 'vue';
import type { AdvancedNode, AdvancedEdge, FlowNote } from '../workflow-advanced-models';
import { PathResult, NodeType, NodeExecutionStatus, HandleType, VF_NODE_TYPE } from '../workflow-advanced-models';
import { getEdgeColor } from './useNodeStatusDisplay';
import { i18n } from 'src/boot/i18n';

/**
 * Execution information for a node
 */
export interface ExecutionInfo {
  execution_status: NodeExecutionStatus;
  completion_time: number;
  error: string | null;
  logs: any[];
  executionOrder?: number;
}

/**
 * Log entry from workflow execution
 */
export interface WorkflowLogEntry {
  id: string;
  workflow_id: string;
  workflow_name: string;
  created_on: string;
  result: PathResult;
  run_time_mili_seconds: number;
  workflow_version: number;
  workflow_data?: {
    nodes: AdvancedNode[];
    edges: AdvancedEdge[];
    notes?: FlowNote[];
    viewport?: { x: number; y: number; zoom: number };
  };
  logs: Array<Array<{
    node_id: string;
    node_type: string;
    status: string;
    duration_ms: number;
    logs: any[];
    error?: string | null;
    targets?: {
      success?: string[];
      failed_condition?: string[];
      error?: string[];
    };
  }>>;
}

/**
 * VueFlow node with execution data
 */
export interface VueFlowNode {
  id: string;
  type: 'logicNode' | 'startNode' | 'controlNode' | 'noteNode';
  position: { x: number; y: number };
  data: {
    nodeId: string;
    card: any;
    nodeType: string;
    cardIndex: number;
    executionStatus?: NodeExecutionStatus;
    executionTime?: number;
    error?: string | null;
    logs?: any[];
    executionOrder?: number;
    // Note node fields
    content?: string;
    color?: string;
    noteWidth?: number;
    noteHeight?: number;
    [key: string]: any;
  };
}

/**
 * VueFlow edge with execution highlighting
 */
export interface VueFlowEdge {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string;
  targetHandle: string;
  animated?: boolean;
  style?: {
    stroke: string;
    strokeWidth: number;
  };
}

/**
 * Transformed workflow log data
 */
export interface TransformedFlowData {
  nodes: VueFlowNode[];
  edges: VueFlowEdge[];
  executionData: Record<string, ExecutionInfo>;
  executedNodesCount: number;
  totalNodesCount: number;
}

/**
 * Composable for workflow log transformation
 */
export function useWorkflowLogTransformation() {
  /**
   * Main transformation function - converts log entry to VueFlow format
   */
  const transformWorkflowLog = (logEntry: WorkflowLogEntry | null): TransformedFlowData | null => {
    if (!logEntry || !logEntry.workflow_data || logEntry.workflow_version !== 3) {
      return null;
    }

    const { nodes: rawNodes, edges: rawEdges } = logEntry.workflow_data;
    if (!rawNodes || rawNodes.length === 0) {
      return null;
    }

    // Extract execution status for each node
    const executionStatusMap = extractExecutionStatus(rawNodes, logEntry.logs);

    // Calculate execution order from timestamps
    const executionOrderMap = calculateExecutionOrder(logEntry.logs);

    // Identify which edges were traversed
    const executedEdgesSet = identifyExecutedPaths(logEntry.logs);

    // Transform nodes
    const transformedNodes: VueFlowNode[] = rawNodes.map((node, index) => {
      const execInfo = executionStatusMap.get(node.node_id);
      const nodeType = getNodeType(node.node_type);

      return {
        id: node.node_id,
        type: nodeType,
        position: node.position || { x: 0, y: 0 },
        data: {
          nodeId: node.node_id,
          card: node.card || null,
          nodeType: node.node_type,
          cardIndex: index,
          label: getNodeLabel(node),
          executionStatus: execInfo?.execution_status,
          executionTime: execInfo?.completion_time,
          error: execInfo?.error || node.error,
          logs: execInfo?.logs || node.logs || [],
          executionOrder: executionOrderMap.get(node.node_id),
        },
      };
    });

    // Inject note nodes from the notes array
    const notes = logEntry.workflow_data?.notes || [];
    notes.forEach((note) => {
      const noteId = note.node_id || (note as any).id;
      if (!noteId) return;
      transformedNodes.push({
        id: noteId,
        type: 'noteNode',
        position: note.position || { x: 0, y: 0 },
        data: {
          nodeId: noteId,
          card: null,
          nodeType: 'note',
          cardIndex: transformedNodes.length,
          content: note.content || '',
          color: note.color || '#fef48a',
          noteWidth: note.width || 280,
          noteHeight: note.height || 80,
        },
      });
    });

    // Transform edges with execution highlighting
    const transformedEdges: VueFlowEdge[] = rawEdges.map((edge) => {
      const sourceHandle = edge.source_handle || PathResult.SUCCESS;
      const edgeKey = `${edge.source_node_id}:${sourceHandle}:${edge.target_node_id}`;
      const isExecuted = executedEdgesSet.has(edgeKey);

      return {
        id: edge.edge_id,
        source: edge.source_node_id,
        target: edge.target_node_id,
        sourceHandle,
        targetHandle: edge.target_handle || HandleType.INPUT,
        animated: isExecuted,
        style: {
          stroke: isExecuted ? getEdgeColor(sourceHandle) : '#999',
          strokeWidth: isExecuted ? 4 : 1.5,
          strokeDasharray: isExecuted ? undefined : '5,5', // Dashed line for non-executed
        },
      };
    });

    // Create execution data map for AdvancedWorkflowViewer
    const executionData: Record<string, ExecutionInfo> = {};
    executionStatusMap.forEach((info, nodeId) => {
      executionData[nodeId] = {
        ...info,
        executionOrder: executionOrderMap.get(nodeId),
      };
    });

    // Count executed nodes
    const executedNodesCount = Array.from(executionStatusMap.values()).filter(
      (info) => info.execution_status !== NodeExecutionStatus.SKIPPED
    ).length;

    return {
      nodes: transformedNodes,
      edges: transformedEdges,
      executionData,
      executedNodesCount,
      totalNodesCount: rawNodes.length,
    };
  };

  /**
   * Extract execution status for each node from logs array
   */
  const extractExecutionStatus = (
    nodes: AdvancedNode[],
    logs: WorkflowLogEntry['logs']
  ): Map<string, ExecutionInfo> => {
    const statusMap = new Map<string, ExecutionInfo>();

    // Initialize all nodes as skipped
    nodes.forEach((node) => {
      statusMap.set(node.node_id, {
        execution_status: NodeExecutionStatus.SKIPPED,
        completion_time: 0,
        error: null,
        logs: [],
      });
    });

    // Flatten logs array (it's an array of arrays)
    const flatLogs = logs.flat();

    // Update status from execution logs
    flatLogs.forEach((logEntry) => {
      if (logEntry && logEntry.node_id) {
        statusMap.set(logEntry.node_id, {
          execution_status: logEntry.status as NodeExecutionStatus,
          completion_time: logEntry.duration_ms || 0,
          error: logEntry.error || null,
          logs: logEntry.logs || [],
        });
      }
    });

    return statusMap;
  };

  /**
   * Identify which edges were traversed during execution.
   *
   * For each node in the logs, we check its execution status to determine
   * which path was taken:
   * - status === PathResult.SUCCESS → only success path edges were executed
   * - status === PathResult.ERROR → only error path edges were executed
   * - status === PathResult.FAILED_CONDITION → only failed_condition path edges were executed
   *
   * For non-branching nodes (WHEN, THEN, control nodes), only success path applies.
   * For AND nodes, the status determines which branch was taken.
   */
  const identifyExecutedPaths = (logs: WorkflowLogEntry['logs']): Set<string> => {
    const executedEdges = new Set<string>();

    // Flatten logs
    const flatLogs = logs.flat();

    flatLogs.forEach((logEntry) => {
      if (logEntry && logEntry.targets) {
        const sourceNodeId = logEntry.node_id;
        const nodeStatus = logEntry.status;
        const nodeType = logEntry.node_type;

        // For AND nodes, only add edges for the path that was actually taken
        if (nodeType === NodeType.AND) {
          if (nodeStatus === PathResult.SUCCESS && logEntry.targets.success) {
            logEntry.targets.success.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.SUCCESS}:${targetNodeId}`);
            });
          } else if (nodeStatus === PathResult.ERROR && logEntry.targets.error) {
            logEntry.targets.error.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.ERROR}:${targetNodeId}`);
            });
          } else if (nodeStatus === PathResult.FAILED_CONDITION && logEntry.targets.failed_condition) {
            logEntry.targets.failed_condition.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.FAILED_CONDITION}:${targetNodeId}`);
            });
          }
        } else {
          // For non-AND nodes (WHEN, THEN, OR, control nodes)
          // Handle success, error, and failed_condition paths
          if (nodeStatus === PathResult.SUCCESS && logEntry.targets.success) {
            logEntry.targets.success.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.SUCCESS}:${targetNodeId}`);
            });
          } else if (nodeStatus === PathResult.ERROR && logEntry.targets.error) {
            logEntry.targets.error.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.ERROR}:${targetNodeId}`);
            });
          } else if (nodeStatus === PathResult.FAILED_CONDITION && logEntry.targets.failed_condition) {
            logEntry.targets.failed_condition.forEach((targetNodeId: string) => {
              executedEdges.add(`${sourceNodeId}:${PathResult.FAILED_CONDITION}:${targetNodeId}`);
            });
          }
        }
      }
    });

    return executedEdges;
  };

  /**
   * Calculate execution order from log timestamps
   */
  const calculateExecutionOrder = (logs: WorkflowLogEntry['logs']): Map<string, number> => {
    const orderMap = new Map<string, number>();

    // Flatten and sort logs by timestamp if available
    const flatLogs = logs.flat().filter((log) => log && log.node_id);

    // For now, use the order they appear in the logs array as execution order
    // TODO: If timestamps are available in logs, sort by timestamp first
    flatLogs.forEach((logEntry, index) => {
      if (logEntry && logEntry.node_id) {
        orderMap.set(logEntry.node_id, index + 1);
      }
    });

    return orderMap;
  };

  /**
   * Get VueFlow node type from workflow node type
   */
  const getNodeType = (nodeType: string): 'logicNode' | 'startNode' | 'controlNode' | 'noteNode' => {
    if (nodeType === NodeType.START) return 'startNode';
    if (nodeType === NodeType.NOTE) return 'noteNode';
    if ([NodeType.DELAY, NodeType.ALL, NodeType.ANY, NodeType.OR].includes(nodeType as NodeType)) return 'controlNode';
    return 'logicNode';
  };

  /**
   * Get node label for display
   */
  const getNodeLabel = (node: AdvancedNode): string => {
    // Use the backend-provided label first (e.g., wf_node_or, wf_node_wait_all)
    const label = node.label ? i18n.t(node.label) : i18n.t(`wf_${node.node_type}`);

    // For control nodes, try to add configuration info
    if (node.node_type === NodeType.DELAY && node.card?.variables) {
      const minutesVar = node.card.variables.find((v: any) => v.display_name === 'minutes');
      if (minutesVar?.data) {
        return `${label}: ${minutesVar.data}m`;
      }
    }

    return label;
  };

  return {
    transformWorkflowLog,
    extractExecutionStatus,
    identifyExecutedPaths,
    calculateExecutionOrder,
  };
}

/**
 * Create a reactive transformation
 */
export function useReactiveWorkflowLogTransformation(logEntry: Ref<WorkflowLogEntry | null>) {
  const { transformWorkflowLog } = useWorkflowLogTransformation();

  const transformed = computed(() => {
    return transformWorkflowLog(logEntry.value);
  });

  return {
    transformedNodes: computed(() => transformed.value?.nodes || []),
    transformedEdges: computed(() => transformed.value?.edges || []),
    executionData: computed(() => transformed.value?.executionData || {}),
    executedNodesCount: computed(() => transformed.value?.executedNodesCount || 0),
    totalNodesCount: computed(() => transformed.value?.totalNodesCount || 0),
  };
}
