<template>
  <span class="orderByParentSpan arrow-color">
    <span
      class="up-arrow orderBy absolute"
      :class="is_order_by_selected('asc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="asc"
      @click="OrderBy"
    ></span>
    <span
      class="down-arrow orderBy absolute"
      :class="is_order_by_selected('desc') ? 'selected' : ''"
      :data-name="column_name"
      data-direction="desc"
      @click="OrderBy"
    ></span>
  </span>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';
import { storeToRefs } from 'pinia';
import { objLen } from 'src/utils/general';

export default defineComponent({
  mixins: [],
  props: {
    column_name: {
      type: String,
      required: true,
    },
    returnSortingObj: {
      type: Boolean,
      default: false,
    },
  },
  components: {},
  watch: {
    order_by: {
      deep: true,
      handler: function (newVal, oldVal) {
        if (oldVal) {
          this.resetSelectedClass(oldVal.field_name, oldVal.direction);
        }
        if (newVal) {
          this.addSelectedClass(newVal.field_name, newVal.direction);
        }
        this.init();
      },
    },
  },
  mounted: function () {
    this.init();
  },
  methods: {
    is_order_by_selected(direction: string) {
      return (
        this.order_by_field == this.column_name &&
        this.order_by_direction == direction
      );
    },

    init() {
      if (objLen(this.order_by) === 0) {
        return;
      }
      this.order_by_field = this.order_by.field_name;
      this.order_by_direction = this.order_by.direction;
      this.resetSelectedClass(this.order_by_field, this.order_by_direction);
      this.addSelectedClass(this.order_by_field, this.order_by_direction);
    },

    OrderBy(ev: any) {
      if (ev.target.classList.contains('selected')) {
        return;
      }

      let direction = ev.target.dataset.direction;
      let fieldName = ev.target.dataset.name;

      //   stores the reference of element to use on page load
      //   LocalStorage.set('sort_by_element_ref', ev.target.id);
      if (!direction || !fieldName) {
        logError('ERROR: Orderby for field', fieldName);
        return;
      }
      ev.target.classList.add('selected');
      this.resetSelectedClass(fieldName, direction);
      this.order_by_field = fieldName;
      this.order_by_direction = direction;

      this.order_by = {
        field_name: this.order_by_field,
        direction: this.order_by_direction,
      };

      this.triggerApplyFilters(this.order_by);
    },

    triggerApplyFilters(orderBy: any) {
      // always reset pagination on sort
      const event = new CustomEvent('wf_apply_filters', {
        detail: { orderBy: orderBy },
      });
      document.dispatchEvent(event);
    },
    addSelectedClass(fieldName: string, direction: string) {
      const orderByElList = document.querySelectorAll<HTMLElement>('.orderBy');
      if (!orderByElList.length) {
        return;
      }
      for (var i = 0; i < orderByElList.length; i++) {
        let column = orderByElList[i];
        if (
          column.dataset.name == fieldName &&
          column.dataset.direction == direction
        ) {
          column.classList.add('selected');
        }
      }
    },
    resetSelectedClass(fieldName: string, direction: string) {
      const orderByElList = document.querySelectorAll<HTMLElement>('.orderBy');
      if (!orderByElList.length) {
        return;
      }
      for (var i = 0; i < orderByElList.length; i++) {
        let column = orderByElList[i];
        if (
          column.dataset.name != fieldName ||
          (column.dataset.name == fieldName &&
            column.dataset.direction != direction)
        ) {
          column.classList.remove('selected');
        }
      }
    },
  },
  setup() {
    const workflow_log_store = useWorkflowLogsVariablesStore();
    const { order_by } = storeToRefs(workflow_log_store);
    return {
      order_by,
      order_by_field: ref(''),
      order_by_direction: ref(''),
    };
  },
});
</script>
