      :zoom-on-scroll="zoomEnabled"
      :zoom-on-pinch="zoomEnabled"
      :zoom-on-double-click="false"
      :pan-on-drag="panEnabled"
      :nodes-draggable="nodesDraggable"
      :nodes-connectable="false"
      :elements-selectable="nodesDraggable"
      :translate-extent="translateExtent"
      :node-extent="cachedNodeExtent"
