      <template #node-logicNode="{ data }">
        <div class="viewer-logic-node" :class="[getExecutionStatusClass(data.executionStatus), { 'node-selected': isNodeSelected(data.nodeId), 'node-on-path': isOnPath(data.nodeId), 'node-not-executed': isNodeNotExecuted(data.executionStatus) }]" @click="handleNodeClick(data.nodeId)">
