          <!-- Input handle (for AND/THEN nodes) -->
          <Handle
            v-if="[NodeType.AND, NodeType.THEN].includes(data.nodeType)"
            type="target"
            :position="Position.Left"
            :id="HandleType.INPUT"
            class="handle handle-input"
            :is-connectable="false"
          />

          <AdvancedWorkflowCard
            v-if="data.card"
            :item="data.card"
            :isDialog="false"
            :parentSvg="data.card.svg"
            :color="data.card.svg_background_color"
            :version="data.card.card_version"
            :itemIndex="data.cardIndex"
            :nodeId="data.nodeId"
            :cardType="data.nodeType"
          />
          <div v-else class="cardless-node-label">
            {{ data.label || data.nodeType }}
          </div>

          <!-- Success handle (for AND nodes - top right) -->
          <Handle
            v-if="data.nodeType === NodeType.AND"
            type="source"
            :position="Position.Right"
            :id="PathResult.SUCCESS"
            :class="[
              'handle',
              'handle-success',
              { 'handle-unused': !data.usedHandles?.includes(PathResult.SUCCESS) }
            ]"
            :is-connectable="false"
          />

          <!-- Failed condition handle (for AND nodes - lower right) -->
          <Handle
            v-if="data.nodeType === NodeType.AND"
            type="source"
            :position="Position.Right"
            :id="PathResult.FAILED_CONDITION"
            :class="[
              'handle',
              'handle-failed-condition',
              { 'handle-unused': !data.usedHandles?.includes(PathResult.FAILED_CONDITION) }
            ]"
            :is-connectable="false"
          />

          <!-- Success handle (for WHEN/THEN nodes) -->
          <Handle
            v-if="[NodeType.WHEN, NodeType.THEN].includes(data.nodeType)"
            type="source"
            :position="Position.Right"
            :id="PathResult.SUCCESS"
            :class="[
              'handle',
              'handle-success',
              { 'handle-unused': !data.usedHandles?.includes(PathResult.SUCCESS) }
            ]"
            :is-connectable="false"
          />

          <!-- Error handle (for AND/THEN nodes - bottom) -->
          <Handle
            v-if="[NodeType.AND, NodeType.THEN].includes(data.nodeType)"
            type="source"
            :position="Position.Bottom"
            :id="PathResult.ERROR"
            :class="[
              'handle',
              'handle-error',
              { 'handle-unused': !data.usedHandles?.includes(PathResult.ERROR) }
            ]"
            :is-connectable="false"
          />

          <!-- Execution Order Badge (top-left) -->
          <div v-if="data.executionOrder" class="execution-order-badge">
            {{ data.executionOrder }}
          </div>

          <!-- Execution Status Overlay (for logs) -->
          <div v-if="data.executionStatus && !isNodeNotExecuted(data.executionStatus)" class="execution-status-overlay">
            <q-badge :color="getNodeStatusColor(data.executionStatus)">
              <q-icon :name="getNodeStatusIcon(data.executionStatus)" size="xs" />
              {{ data.executionTime ? data.executionTime + 'ms' : '' }}
            </q-badge>
          </div>
        </div>
      </template>

      <!-- START Node Template -->
      <template #node-startNode="{ data }">
        <div class="viewer-start-node" :class="[getExecutionStatusClass(data.executionStatus), { 'node-selected': isNodeSelected(data.nodeId), 'node-on-path': isOnPath(data.nodeId), 'node-not-executed': isNodeNotExecuted(data.executionStatus) }]" @click="handleNodeClick(data.nodeId)">
          <div class="start-node-inner">
            <q-icon name="cancel" size="36px" color="white" />
          </div>

          <!-- Success handle -->
          <Handle
            type="source"
            :position="Position.Right"
            :id="PathResult.SUCCESS"
            :class="[
              'handle',
              'handle-success',
              { 'handle-unused': !data.usedHandles?.includes(PathResult.SUCCESS) }
            ]"
            :is-connectable="false"
          />

          <!-- Execution Order Badge -->
          <div v-if="data.executionOrder" class="execution-order-badge execution-order-badge-start">
            {{ data.executionOrder }}
          </div>

          <div v-if="data.executionStatus && !isNodeNotExecuted(data.executionStatus)" class="execution-status-badge">
            <q-icon
