          :class="['control-node-' + data.nodeType, getExecutionStatusClass(data.executionStatus), { 'node-selected': isNodeSelected(data.nodeId), 'node-on-path': isOnPath(data.nodeId), 'node-not-executed': isNodeNotExecuted(data.executionStatus) }]"
