            :position="Position.Left"
            :id="HandleType.INPUT"
            class="handle control-node-handle-input handle-input"
            :is-connectable="false"
          />

          <div class="control-node-content">
            <div class="control-node-icon-wrapper">
              <q-icon :name="getControlNodeIcon(data.nodeType)" size="24px" />
            </div>
            <span class="control-node-label">{{ $t(data.label) }}</span>
          </div>

          <!-- Success handle -->
          <Handle
            type="source"
            :position="Position.Right"
