<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { VueFlow, Handle, Position } from '@vue-flow/core';
import { MiniMap, Background } from '@vue-flow/additional-components';
import AdvancedWorkflowCard from '../AdvancedWorkflowCard.vue';
import { PathResult, NodeType, HandleType } from '../workflow-advanced-models';
import { getExecutionTree } from './workflowGraphUtils';
import { populateWorkflowModelForCard, maskSensitiveCardVariables } from '../composables/useCardVariableResolver';
import {
  getNodeStatusIcon, getNodeStatusColor, getNodeStatusHexColor, getControlNodeIcon,
  isNodeNotExecuted, getExecutionStatusClass, getNodeColor, calculateHandleUsage, calculateNodeBounds, buildNodeData,
} from '../composables/useNodeStatusDisplay';

export default defineComponent({
  name: 'AdvancedWorkflowViewer',
  components: {
    VueFlow,
    Handle,
    MiniMap,
    Background,
    AdvancedWorkflowCard,
  },
  props: {
    nodes: {
      type: Array as PropType<any[]>,
      required: true,
    },
    edges: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
    readOnly: {
      type: Boolean,
      default: true,
    },
    nodesDraggable: {
      type: Boolean,
      default: false,
    },
    zoomEnabled: {
      type: Boolean,
      default: true,
    },
    panEnabled: {
      type: Boolean,
      default: true,
    },
    showBackground: {
      type: Boolean,
      default: true,
    },
    showMinimap: {
      type: Boolean,
      default: false,
    },
    executionData: {
      type: Object as PropType<Record<string, any>>,
      default: () => ({}),
    },
    selectedNodeId: {
      type: String as PropType<string | null>,
      default: null,
    },
    /** Max pixels a node can be dragged beyond the current bounding box before dropping */
    dragPadding: {
      type: Number,
      default: 600,
    },
  },
  emits: ['node-click'],

  data() {
    return {
      viewerNodes: [] as any[],
      viewerEdges: [] as any[],
      // Cached node extent - only updates when dragging stops
      cachedNodeExtent: [[-500, -500], [2000, 2000]] as [[number, number], [number, number]],
      // Up/downstream path highlighting (node dotted borders only)
      treeHighlightSet: null as Set<string> | null,
      // Expose constants and helpers for template usage
      Position,
      PathResult,
      NodeType,
      HandleType,
      getNodeStatusIcon,
      getNodeStatusColor,
      getNodeStatusHexColor,
      getControlNodeIcon,
    };
  },

  computed: {
    /** Calculate which handles are actually used (have outgoing edges) */
    handleUsage(): Record<string, Set<string>> {
      return calculateHandleUsage(this.nodes, this.edges);
    },

    /** Calculate panning bounds based on node positions with padding - uses viewerNodes so bounds expand with dragged cards */
    translateExtent(): [[number, number], [number, number]] {
      const nodesToUse = this.viewerNodes.length > 0 ? this.viewerNodes : this.nodes;
      return calculateNodeBounds(nodesToUse, 500, 400, 400, [[-1000, -1000], [1000, 1000]]);
    },

  },

  watch: {
    nodes: {
      handler() {
        this.updateViewerNodes();
      },
      immediate: true,
      deep: true,
    },
    edges: {
      handler() {
        this.viewerEdges = this.edges.map((edge: any) => ({ ...edge }));
      },
      immediate: true,
      deep: true,
    },
    executionData: {
      handler() {
        this.updateViewerNodes();
      },
      deep: true,
    },
    selectedNodeId(newVal: string | null) {
      if (newVal) {
        this.applyTreeHighlight(newVal);
      } else {
        this.clearTreeHighlight();
      }
    },
  },

  methods: {
    /** Build a node with execution data merged in */
    buildNode(node: any): any {
      try {
        const usedHandles = this.handleUsage[node.node_id || node.id] || new Set();

        // Mask sensitive DocOperator values and populate workflowModel for Badge.vue
        if (node.data?.card) {
          maskSensitiveCardVariables(node.data.card);
          populateWorkflowModelForCard(node.data.card);
        }

        return buildNodeData(node, this.executionData, usedHandles);
      } catch (err) {
        console.error(
          '[AdvancedWorkflowViewer] buildNode failed for node',
          node?.node_id || node?.id,
          err,
        );
        return node;
      }
    },

    /** Update viewer nodes, preserving dragged positions */
    updateViewerNodes() {
      if (this.viewerNodes.length === 0) {
        this.viewerNodes = this.nodes.map((node) => this.buildNode(node));
      } else {
        const positionMap = new Map<string, { x: number; y: number }>();
        this.viewerNodes.forEach((n: any) => {
          const id = n.node_id || n.id;
          if (n.position) {
            positionMap.set(id, { ...n.position });
          }
        });

        this.viewerNodes = this.nodes.map((node: any) => {
          const built = this.buildNode(node);
          const nodeId = node.node_id || node.id;
          const savedPosition = positionMap.get(nodeId);
          if (savedPosition) {
            built.position = savedPosition;
          }
          return built;
        });
      }
      this.updateNodeExtent();
    },

    isNodeSelected(nodeId: string): boolean {
      return this.selectedNodeId === nodeId;
    },

    getNodeColor,
    isNodeNotExecuted,
    getExecutionStatusClass,

    handleNodeClick(nodeId: string) {
      this.$emit('node-click', nodeId);
    },

    /** Compute up/downstream tree and highlight path nodes + edges */
    applyTreeHighlight(nodeId: string) {
      const nodeTypes = new Map<string, string>();
      for (const node of this.nodes) {
        const id = node.node_id || node.id;
        if (node.data?.nodeType) nodeTypes.set(id, node.data.nodeType);
      }

      const tree = getExecutionTree(nodeId, this.edges, nodeTypes);

      const pathNodes = new Set<string>([nodeId, ...tree.upstream, ...tree.downstream]);
      this.treeHighlightSet = pathNodes;
    },

    clearTreeHighlight() {
      this.treeHighlightSet = null;
    },

    isOnPath(nodeId: string): boolean {
      if (!this.treeHighlightSet) return false;
      return this.treeHighlightSet.has(nodeId) && !this.isNodeSelected(nodeId);
    },

    /** Handle node drag stop - update extent so bounds expand to include new position */
    handleNodeDragStop() {
      this.updateNodeExtent();
    },

    updateNodeExtent() {
      const nodesToUse = this.viewerNodes.length > 0 ? this.viewerNodes : this.nodes;
      this.cachedNodeExtent = calculateNodeBounds(
        nodesToUse, this.dragPadding, 400, 200, [[-500, -500], [2000, 2000]],
      );
    },

  },
});
</script>

